# huginn_state_glyph KEY - the glyph on a UTF-8 locale, the 7-bit mark otherwise.
huginn_state_glyph() {
  local g="HUGINN_GLYPH_$1" m="HUGINN_MARK_$1"
  case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
    *[Uu][Tt][Ff]-8*|*[Uu][Tt][Ff]8*) printf '%s' "${!g:-}" ;;
    *) printf '%s' "${!m:-}" ;;
  esac
}
